const systemStreamProviderName = `-- name: SystemStreamProviderName :one
SELECT p.name
FROM routing_rules r
JOIN providers p ON p.id = (r.splits -> 0 ->> 'provider_id')::uuid AND p.disconnected_at IS NULL
WHERE r.workspace_id = $1 AND r.stream = 'system' AND r.enabled AND r.conditions = '{}'::jsonb
ORDER BY r.priority
LIMIT 1
`

// The provider of the default System-stream route of a workspace (read-only
// view of the routing domain, for "emails go out … via Postmark").
func (q *Queries) SystemStreamProviderName(ctx context.Context, workspaceID uuid.UUID) (string, error) {
	row := q.db.QueryRow(ctx, systemStreamProviderName, workspaceID)
	var name string
	err := row.Scan(&name)
	return name, err
}

